   "source": "// Functions are declared at module scope. Parameters and the return type are\n// always annotated: nothing crosses a call boundary untyped.\n\nfunction add(a: int32, b: int32): int32 {\n  return a + b;\n}\n\n// There are no implicit numeric conversions, in either direction, so the\n// widening is written out.\nfunction half(n: int32): float32 {\n  return float32(n) / 2.0;\n}\n\n// `ref` is written at the declaration AND at the call, so a function that\n// mutates its argument cannot do it quietly.\nfunction bump(ref n: int32): void {\n  n = n + 1;\n}\n\nfunction main(): int32 {\n  let total: int32 = add(2, 3);\n  bump(ref total);\n\n  const label = \"total\";      // const cannot be rebound; the type is inferred\n  printf(`${label}=${total}\\n`);\n\n  const share: float32 = half(total);\n  if (share > 2.0) {\n    printf(\"over two\\n\");\n  }\n\n  return 0;\n}\n",
