   "source": "// A kind is the third axis. A type says what a value IS, a trait says what it\n// CAN DO, a kind says how the BINDING must be USED. Same type, two bindings,\n// different obligations.\n//\n// `disposable` is not built in. This is its entire declaration, from\n// std/core/kinds.yoop:\n//\n//   export kind disposable {\n//     appliesTo binding;                  // attaches to a let/const site\n//     requires Disposable;                // the type must implement it\n//     mustCall dispose beforeScopeEnd;    // inject the call at scope exit\n//     ownsBlock;                          // may take a trailing { } block\n//   }\n\nimport { Disposable, disposable } from \"std/core/kinds.yoop\";\n\ntype Conn implements Disposable {\n  id: int32,\n  function dispose(ref self): void {\n    printf(`  close ${self.id}\\n`);\n  }\n}\n\n// A plain binding carries no obligation, so nothing is injected - and nothing\n// complains. Ownership is advisory until you ask for it.\nfunction plain(): void {\n  printf(\"plain:\\n\");\n  let c: Conn = { id: 1 };\n  printf(`  use ${c.id}\\n`);\n}\n\n// One word of difference, and the compiler places the dispose call for you.\nfunction kinded(): void {\n  printf(\"kinded:\\n\");\n  disposable c: Conn = { id: 2 };\n  printf(`  use ${c.id}\\n`);\n}\n\n// Including on the early return. You declare the obligation once instead of\n// remembering it on every branch.\nfunction bail(early: bool): void {\n  printf(\"bail:\\n\");\n  disposable c: Conn = { id: 3 };\n  if (early) {\n    return;\n  }\n  printf(\"  not reached\\n\");\n}\n\nfunction main(): int32 {\n  plain();\n  kinded();\n  bail(true);\n  return 0;\n}\n",
